/* ERZEUGT - nicht von Hand aendern.
 *
 * Gebaut von werkzeuge/auffangnetz_bauen.py aus statisch/. Aenderungen
 * hier gehen beim naechsten Lauf verloren; wer das Aussehen der
 * Notfassung aendern will, aendert die echte Seite und baut neu:
 *
 *     python werkzeuge/auffangnetz_bauen.py
 *
 * Enthalten sind das Stylesheet der oeffentlichen Seite, die Schriften,
 * Wappen, Logo, Favicon und die im Dashboard gepflegten Bloecke der
 * Startseite. Alles als Text, weil ein Worker keine zweite Datei
 * nachladen kann - der Server, von dem sie kaeme, ist der ausgefallene.
 */

export const SCHRIFTEN = "@font-face{font-family:'IBM Plex Sans';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}\n@font-face{font-family:'IBM Plex Sans';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}\n@font-face{font-family:'IBM Plex Sans';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}\n@font-face{font-family:'Space Grotesk';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}\n@font-face{font-family:'Space Grotesk';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}\n@font-face{font-family:'Space Grotesk';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}\n@font-face{font-family:'IBM Plex Mono';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}";

export const STIL = "/* --- stil/basis.css --- */\n/* ===========================================================================\r\n   Wirtschafts- & Investment-AG - Grundgestaltung\r\n   ===========================================================================\r\n   Dieselbe Markenwelt wie in V1: Navy als Traeger, Amber als Akzent, Space\r\n   Grotesk fuer Ueberschriften, IBM Plex fuer Text und Zahlen. Neu ist die\r\n   Ordnung dahinter.\r\n\r\n   In V1 standen die Werte verstreut im Stylesheet: sieben verschiedene\r\n   Abstaende zwischen Bloecken, drei Schriftgroessen fuer dieselbe Art\r\n   Ueberschrift, Knopfhoehen, die sich um zwei Pixel unterschieden. Jetzt gibt\r\n   es je eine Skala fuer Abstand, Schriftgroesse, Rundung und Schatten - und\r\n   nichts ausserhalb davon.\r\n   ========================================================================= */\r\n\r\n/* --- 1. Werte ----------------------------------------------------------- */\r\n:root{\r\n  /* Farben - hell */\r\n  --bg:#F6F7F4;\r\n  --bg-tief:#EEF2EF;\r\n  --flaeche:#FFFFFF;\r\n  --flaeche-2:#EEF2EF;\r\n  --flaeche-3:#E4EAE6;\r\n  --text:#18211F;\r\n  --text-stark:#101917;\r\n  --gedaempft:#66726D;\r\n  --gedaempft-2:#8A9691;\r\n  --linie:rgba(24,33,31,0.12);\r\n  --linie-stark:rgba(24,33,31,0.22);\r\n\r\n  --navy:#0E2647;\r\n  --navy-tief:#081A33;\r\n  --navy-weich:#1E3F6E;\r\n  --navy-hauch:rgba(14,38,71,0.08);\r\n  --navy-schrift:#FFFFFF;\r\n\r\n  --amber:#B7791F;\r\n  --amber-hell:#D9A441;\r\n  --amber-hauch:rgba(183,121,31,0.10);\r\n  --gruen:#2F855A;\r\n  --rot:#C53030;\r\n  --blau:#2B6CB0;\r\n  --lila:#805AD5;\r\n  --kontrast:#FFFFFF;\r\n\r\n  /* Abstaende - eine Skala, sonst nichts */\r\n  --r1:.25rem; --r2:.5rem; --r3:.75rem; --r4:1rem;\r\n  --r5:1.5rem; --r6:2rem; --r7:3rem; --r8:4.5rem;\r\n\r\n  /* Rundungen und Schatten */\r\n  --rund:10px; --rund-klein:7px; --rund-voll:999px;\r\n  --schatten:0 1px 2px rgba(24,33,31,.05), 0 14px 34px -26px rgba(24,33,31,.32);\r\n  --schatten-hoch:0 2px 6px rgba(24,33,31,.07), 0 24px 48px -28px rgba(24,33,31,.40);\r\n\r\n  /* Schrift */\r\n  --schrift:'IBM Plex Sans', system-ui, -apple-system, sans-serif;\r\n  --schrift-titel:'Space Grotesk', system-ui, sans-serif;\r\n  --schrift-mono:'IBM Plex Mono', ui-monospace, monospace;\r\n\r\n  /* Seitenrand: waechst mit dem Fenster mit. Ein gemeinsamer Wert fuer\r\n     Kopfzeile, Ticker und Inhalt - sonst stehen Logo und Text auf zwei\r\n     verschiedenen Kanten. */\r\n  --seitenrand:clamp(1.5rem, 3.2vw, 4.5rem);\r\n\r\n  --pfeil:url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 8'%3E%3Cpath fill='none' stroke='%2366726D' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round' d='M1 1.5 6 6.5l5-5'/%3E%3C/svg%3E\");\r\n  --tempo:.18s;\r\n}\r\n@media (max-width:1100px){ :root{ --seitenrand:1.4rem; } }\r\n@media (max-width:720px){ :root{ --seitenrand:1rem; } }\r\n\r\n/* Dunkelmodus: kein Invertieren, sondern eine eigene Nachtpalette. Gedaempftes\r\n   Mitternachtsblau statt Schwarz, damit Amber weiter als warmer Akzent wirkt. */\r\nhtml[data-theme=\"dark\"]{\r\n  /* Gemessen lag der alte Grund bei einer Helligkeit von 4 von 100 - das ist\r\n     praktisch Schwarz, und eine Marke, die auf Marineblau gebaut ist, sieht\r\n     darauf aus wie ausgeschaltet. Etwas angehoben und blaeulich: dunkel\r\n     bleibt dunkel, aber die Seite hat wieder eine Farbe. */\r\n  --bg:#0D1526;\r\n  --bg-tief:#080D18;\r\n  /* Die Stufen liegen bewusst weiter auseinander als vorher: Auf dunklem\r\n     Grund braucht ein Unterschied mehr Abstand, um ueberhaupt als\r\n     Unterschied gelesen zu werden. Vorher lagen Grund und Flaeche neun\r\n     Helligkeitsstufen auseinander - zu wenig, um eine Karte als Karte zu\r\n     erkennen. */\r\n  --flaeche:#161F33;\r\n  --flaeche-2:#1F2942;\r\n  --flaeche-3:#2A3752;\r\n  --text:#EDF0F7;\r\n  --text-stark:#F6F8FC;\r\n  --gedaempft:#9AA7C2;\r\n  --gedaempft-2:#6C7791;\r\n  --linie:rgba(237,240,247,0.10);\r\n  --linie-stark:rgba(237,240,247,0.20);\r\n\r\n  --navy:#82A6F2;\r\n  --navy-tief:#05080F;\r\n  --navy-weich:#3A4A6B;\r\n  --navy-hauch:rgba(130,166,242,0.14);\r\n  --navy-schrift:#081222;\r\n\r\n  /* Etwas heller und weniger gesaettigt als im Hellmodus: Reines Orange auf\r\n     Marineblau wirkt billig und ist als Schrift schlechter zu lesen. */\r\n  --amber:#EFB95C;\r\n  --amber-hell:#F5D08C;\r\n  --amber-hauch:rgba(232,168,61,0.13);\r\n  --gruen:#5FC28A;\r\n  --rot:#E2726B;\r\n  --blau:#6FA3E0;\r\n  --lila:#B794F4;\r\n  --kontrast:#0A0F1A;\r\n\r\n  --schatten:inset 0 1px 0 rgba(255,255,255,.04), 0 16px 36px -26px rgba(0,0,0,.7);\r\n  --schatten-hoch:inset 0 1px 0 rgba(255,255,255,.06), 0 26px 54px -28px rgba(0,0,0,.8);\r\n  --pfeil:url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 8'%3E%3Cpath fill='none' stroke='%239AA7C2' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round' d='M1 1.5 6 6.5l5-5'/%3E%3C/svg%3E\");\r\n}\r\n\r\n/* --- 2. Grundgeruest ---------------------------------------------------- */\r\n*, *::before, *::after{ box-sizing:border-box; }\r\n/* Muss staerker sein als jede display-Regel weiter unten: der Browser bringt\r\n   zwar [hidden]{display:none} mit, aber schon \"label{display:flex}\" schlaegt\r\n   sie. In V1 standen deshalb Formularfelder da, die versteckt sein sollten. */\r\n[hidden]{ display:none !important; }\r\n\r\nhtml{ min-height:100%; background:var(--bg); -webkit-text-size-adjust:100%; }\r\nbody{\r\n  margin:0; min-height:100vh; min-height:100dvh;\r\n  display:flex; flex-direction:column;\r\n  background:linear-gradient(180deg, #FFFFFF 0%, var(--bg) 30%, var(--bg-tief) 100%);\r\n  color:var(--text);\r\n  font-family:var(--schrift); font-size:16px; line-height:1.6;\r\n  -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility;\r\n}\r\nhtml[data-theme=\"dark\"] body{\r\n  /* Vorher lief der Grund von #111c33 oben nach fast Schwarz unten. Oben war\r\n     er damit HELLER als die Kaesten, die darauf liegen - die sahen aus wie\r\n     Loecher statt wie Karten, und die halbe Seite wirkte verwaschen. Jetzt\r\n     eine ruhige Flaeche mit einem kaum sichtbaren Schimmer im Kopfbereich:\r\n     genug Tiefe, um nicht flach zu sein, aber nirgends heller als das, was\r\n     darauf liegt. */\r\n  background:var(--bg);\r\n  background-image:radial-gradient(120% 70% at 50% -10%,\r\n                   rgba(130,166,242,.10) 0%, transparent 60%);\r\n  background-attachment:fixed;\r\n}\r\nbody > main{ flex:1 0 auto; }\r\nbody > footer.seite{ flex-shrink:0; }\r\n\r\nh1,h2,h3,h4{\r\n  font-family:var(--schrift-titel); font-weight:600; color:var(--text-stark);\r\n  margin:0 0 var(--r2); letter-spacing:-.01em; line-height:1.22;\r\n  text-wrap:balance;\r\n}\r\nh1{ font-size:clamp(1.75rem, 1.2rem + 2.2vw, 2.5rem); }\r\nh2{ font-size:clamp(1.35rem, 1.1rem + 1.1vw, 1.75rem); }\r\nh3{ font-size:1.15rem; }\r\nh4{ font-size:1rem; }\r\np{ margin:0 0 var(--r3); }\r\np:last-child{ margin-bottom:0; }\r\n\r\na{ color:var(--amber); text-decoration:none; }\r\na:hover{ text-decoration:underline; }\r\ncode, kbd, samp{ font-family:var(--schrift-mono); font-size:.88em; }\r\n\r\nhr{ border:0; border-top:1px solid var(--linie); margin:var(--r5) 0; }\r\n\r\n::selection{ background:var(--amber-hauch); color:var(--text-stark); }\r\n\r\n/* Ein sichtbarer, einheitlicher Fokusring. In V1 hatte jedes Element seinen\r\n   eigenen - Tastaturbedienung war dadurch stellenweise nicht nachvollziehbar. */\r\n:focus-visible{\r\n  outline:3px solid color-mix(in srgb, var(--blau) 45%, transparent);\r\n  outline-offset:2px; border-radius:var(--rund-klein);\r\n}\r\n:focus:not(:focus-visible){ outline:none; }\r\n\r\n.nur-lesehilfe{\r\n  position:absolute; width:1px; height:1px; padding:0; margin:-1px;\r\n  overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0;\r\n}\r\n/* Sprungmarke fuer die Tastatur - der erste Tabstopp jeder Seite. */\r\n.sprung{\r\n  position:absolute; left:var(--r3); top:-4rem; z-index:200;\r\n  background:var(--navy); color:var(--navy-schrift);\r\n  padding:var(--r2) var(--r4); border-radius:var(--rund-klein);\r\n  transition:top var(--tempo) ease;\r\n}\r\n.sprung:focus{ top:var(--r3); text-decoration:none; }\r\n\r\n.hut{\r\n  font-family:var(--schrift-mono); text-transform:uppercase;\r\n  letter-spacing:.12em; font-size:.72rem; color:var(--amber);\r\n  display:block; margin-bottom:var(--r2);\r\n}\r\n.meta{ color:var(--gedaempft); font-size:.86rem; }\r\n.gedaempft{ color:var(--gedaempft); }\r\n.mono{ font-family:var(--schrift-mono); }\r\n.zentriert{ text-align:center; }\r\n.nowrap{ white-space:nowrap; }\r\n\r\n@media (prefers-reduced-motion: reduce){\r\n  *, *::before, *::after{\r\n    animation-duration:.01ms !important; animation-iteration-count:1 !important;\r\n    transition-duration:.01ms !important; scroll-behavior:auto !important;\r\n  }\r\n}\r\n\r\n/* --- 3. Kopf- und Fusszeile --------------------------------------------- */\r\nheader.seite{\r\n  display:flex; align-items:center; justify-content:space-between;\r\n  gap:var(--r3); flex-wrap:wrap;\r\n  /* Im App-Modus (Startbildschirm) reicht die Seite unter die Statusleiste\r\n     des Geraets - so ist es gewollt, sonst laege ueber der Kopfleiste ein\r\n     grauer Balken. Nur muss der Inhalt dann auch darunter anfangen: ohne\r\n     diesen Abstand lagen Logo und Menue hinter Uhrzeit und Akku, oben\r\n     abgeschnitten. env() ist im normalen Browser 0 - dort aendert sich\r\n     nichts. Die Seitenwerte sind fuer Querformat: dort frisst die Kerbe\r\n     links oder rechts einen Streifen. */\r\n  padding-top:calc(var(--r3) + env(safe-area-inset-top, 0px));\r\n  padding-bottom:var(--r3);\r\n  padding-left:calc(var(--seitenrand) + env(safe-area-inset-left, 0px));\r\n  padding-right:calc(var(--seitenrand) + env(safe-area-inset-right, 0px));\r\n  border-bottom:3px solid var(--navy);\r\n  /* Erst der schlichte Wert, dann der durchscheinende. Kennt ein Browser\r\n     color-mix() nicht (Safari vor 16.2), verwirft er nur die zweite Zeile -\r\n     und die Kopfleiste hat trotzdem einen Hintergrund. Ohne den scrollte der\r\n     Text sichtbar hinter ihr durch. */\r\n  background:var(--flaeche);\r\n  background:color-mix(in srgb, var(--flaeche) 92%, transparent);\r\n  backdrop-filter:blur(12px); -webkit-backdrop-filter:blur(12px);\r\n  /* 58 und nicht 30: Die Menue-Schublade des Dashboards legt einen Schleier\r\n     ueber die Seite (z-index 55). Der lag bisher AUCH ueber der Kopfleiste -\r\n     kaum tippte man auf das Menue, waren Logo, Menueknopf und Hell/Dunkel-\r\n     Schalter hinter einer grauen Scheibe verschwunden. Gemeldet als \"der\r\n     Menue-Knopf geht weg, wenn man draufklickt\".\r\n     Unter der Schublade selbst (60) bleibt die Leiste trotzdem: Die soll sich\r\n     darueberschieben, sonst ragt der Kopf mitten hinein. */\r\n  position:sticky; top:0; z-index:58;\r\n  box-shadow:0 2px 8px rgba(0,0,0,.05);\r\n}\r\n/* Im App-Modus ein garantierter Mindestabstand.\r\n\r\n   Gemeldet: \"ist immernoch verdeckt\". env(safe-area-inset-top) allein reicht\r\n   nicht - manche iPhone-Fassungen melden hier 0, obwohl die Statusleiste sehr\r\n   wohl ueber der Seite liegt. Dann steht rechnerisch alles richtig und\r\n   praktisch trotzdem die Uhr im Logo.\r\n\r\n   max() nimmt, was groesser ist: den echten Wert des Geraets, wenn er kommt -\r\n   sonst 2,9rem, was ueber jeder Statusleiste liegt, die Apple je hatte\r\n   (44 px, mit Dynamic Island 54 px). Im Browser greift die Regel gar nicht,\r\n   dort fehlt data-app. */\r\nhtml[data-app] header.seite{\r\n  padding-top:calc(var(--r2) + max(env(safe-area-inset-top, 0px), 2.9rem));\r\n}\r\nhtml[data-theme=\"dark\"] header.seite{\r\n  /* Vorher nahm die Kopfleiste im Dunkeln die Farbe des Seitengrunds - dann\r\n     ist sie keine Leiste mehr, sondern nur eine Stelle, an der zufaellig\r\n     etwas steht. Gemessen: 0,4 Helligkeitsstufen Unterschied. Jetzt liegt\r\n     sie eine Stufe darueber, wie im Hellmodus auch. */\r\n  background:var(--flaeche);\r\n  background:color-mix(in srgb, var(--flaeche) 86%, transparent);\r\n  box-shadow:0 1px 0 var(--linie), 0 6px 24px rgba(0,0,0,.45);\r\n}\r\nheader.seite .marke-logo{\r\n  display:flex; align-items:center; gap:var(--r3);\r\n  font-family:var(--schrift-titel); font-weight:700; font-size:1.08rem;\r\n  color:var(--navy); text-decoration:none;\r\n}\r\nheader.seite .marke-logo:hover{ text-decoration:none; }\r\nheader.seite .marke-logo img{ height:42px; width:auto; display:block; }\r\n\r\n/* Das Wappen auf dunklem Grund ---------------------------------------------\r\n   Das Wappen ist dunkelblau mit einer hellen Kante. Auf weissem Papier traegt\r\n   diese Kante das Bild; auf dunklem Grund verschwindet sie, und uebrig bleibt\r\n   ein blauer Fleck mit Aehren daneben - genau so sah es im Dunkelmodus aus.\r\n   Ein schmaler weisser Saum stellt es wieder frei. Bewusst kein Leuchten:\r\n   zwei enge Schatten ergeben eine Kante, ein weiter Radius ergaebe Nebel.\r\n   Der Saum muss zur Anzeigegroesse passen; was bei 300 Pixeln eine feine\r\n   Linie ist, verschluckt ein 42 Pixel hohes Bild. Deshalb --saum. */\r\nhtml[data-theme=\"dark\"] img.wappen{\r\n  filter:\r\n    drop-shadow(0 0 var(--saum, 1px) rgba(255,255,255,.88))\r\n    drop-shadow(0 0 var(--saum, 1px) rgba(255,255,255,.88));\r\n}\r\n.marke-text{ display:flex; flex-direction:column; line-height:1.15; }\r\n.marke-motto{\r\n  font-weight:500; font-size:.7rem; color:var(--gedaempft); margin-top:.15rem;\r\n}\r\n\r\nheader.seite nav{ display:flex; align-items:center; gap:var(--r1); }\r\nheader.seite nav a{\r\n  font-family:var(--schrift-mono); font-size:.74rem; text-transform:uppercase;\r\n  letter-spacing:.06em; color:var(--text);\r\n  padding:var(--r2) var(--r3); border-radius:var(--rund-klein);\r\n}\r\nheader.seite nav a:hover{\r\n  color:var(--navy); background:var(--navy-hauch); text-decoration:none;\r\n}\r\nheader.seite nav a.betont{\r\n  background:var(--navy); color:var(--navy-schrift);\r\n}\r\nheader.seite nav a.betont:hover{ background:var(--amber); color:#fff; }\r\n\r\n.burger{\r\n  display:none; background:none; border:1px solid transparent;\r\n  padding:var(--r2) var(--r3); border-radius:var(--rund-klein);\r\n  cursor:pointer; color:var(--navy); min-height:0;\r\n}\r\n.burger-striche{ display:flex; flex-direction:column; gap:4px; width:20px; }\r\n.burger-striche span{\r\n  display:block; height:2px; background:currentColor; border-radius:2px;\r\n}\r\n.burger:hover{ background:var(--navy-hauch); }\r\n/* Geraete ohne Mauszeiger kennen kein Ueberfahren - dort darf das Antippen\r\n   keinen bleibenden Zustand hinterlassen. In V1 blieb der Knopf danach\r\n   dauerhaft eingefaerbt, bis man woanders hintippte. */\r\n@media (hover:none){ .burger:hover{ background:none; } }\r\n\r\n/* Der Hell/Dunkel-Schalter.\r\n   min-height:0 ist hier kein Schoenheitsfehler, sondern Pflicht: die\r\n   allgemeine Knopfregel weiter unten setzt min-height:2.6rem. Die schlaegt\r\n   height:26px, weil eine Mindesthoehe immer gewinnt. Der Schalter war\r\n   dadurch 42px hoch, waehrend der runde Griff bei top:2px klebte - er sass\r\n   sichtbar zu hoch in einer zu grossen Pille.\r\n   Ebenso muessen Hintergrund und Schriftfarbe beim Ueberfahren\r\n   zurueckgenommen werden: sonst faerbt button:hover die ganze Pille amber. */\r\n.thema-schalter{\r\n  position:relative; width:52px; height:28px; min-height:0; flex-shrink:0;\r\n  border-radius:var(--rund-voll); border:1px solid var(--linie);\r\n  background:var(--flaeche-2); padding:0; cursor:pointer;\r\n  display:inline-flex; align-items:center; margin-left:var(--r3);\r\n  transition:background var(--tempo) ease, border-color var(--tempo) ease;\r\n}\r\n.thema-schalter:hover{\r\n  background:var(--flaeche-3); border-color:var(--amber); color:inherit;\r\n}\r\n.thema-schalter:active{ transform:none; }\r\n.thema-schalter:focus-visible{\r\n  outline:2px solid var(--blau); outline-offset:2px;\r\n}\r\n.thema-schalter .knopf{\r\n  position:absolute; top:50%; left:3px; width:22px; height:22px;\r\n  border-radius:50%; display:flex; align-items:center; justify-content:center;\r\n  background:linear-gradient(135deg, var(--amber-hell), var(--amber));\r\n  color:#fff; box-shadow:0 1px 4px rgba(0,0,0,.28);\r\n  transform:translate(0, -50%);\r\n  transition:transform .26s cubic-bezier(.4,0,.2,1), background var(--tempo) ease;\r\n}\r\n.thema-schalter svg{ width:13px; height:13px; display:block; }\r\n.thema-schalter .mond{ display:none; }\r\nhtml[data-theme=\"dark\"] .thema-schalter{ background:var(--flaeche-3); }\r\nhtml[data-theme=\"dark\"] .thema-schalter .knopf{\r\n  transform:translate(24px, -50%);\r\n  background:linear-gradient(135deg, #33507F, var(--navy-weich));\r\n}\r\nhtml[data-theme=\"dark\"] .thema-schalter .sonne{ display:none; }\r\nhtml[data-theme=\"dark\"] .thema-schalter .mond{ display:block; }\r\n/* Wer \"weniger Bewegung\" eingestellt hat, bekommt keinen gleitenden Griff. */\r\n@media (prefers-reduced-motion:reduce){\r\n  .thema-schalter .knopf{ transition:none; }\r\n}\r\n\r\n.ticker{\r\n  background:var(--navy-tief); border-bottom:1px solid var(--navy);\r\n  font-family:var(--schrift-mono); font-size:.68rem; letter-spacing:.06em;\r\n  color:#F6D48B; text-transform:uppercase;\r\n  padding:var(--r2) var(--seitenrand); overflow-x:auto; white-space:nowrap;\r\n  scrollbar-width:none;\r\n}\r\n/* Im Hellmodus ist das Band ein dunkler Streifen unter der hellen Leiste -\r\n   ein Akzent. Im Dunkelmodus war es DUNKLER als die ohnehin dunkle Seite\r\n   (Helligkeit 1,9 gegen 4,3): ein schwarzer Riegel quer ueber den Kopf.\r\n   Jetzt gehoert es zur Kopfleiste, abgesetzt nur durch eine Linie. */\r\nhtml[data-theme=\"dark\"] .ticker{\r\n  background:color-mix(in srgb, var(--flaeche) 70%, var(--bg));\r\n  border-bottom-color:var(--linie);\r\n  color:var(--amber-hell);\r\n}\r\n.ticker::-webkit-scrollbar{ display:none; }\r\n.ticker span:not(:last-child)::after{\r\n  content:\"\u00b7\"; color:var(--gedaempft-2); margin:0 1.2rem;\r\n}\r\n\r\nmain{\r\n  width:100%; max-width:1020px; margin:0 auto;\r\n  /* Im Querformat liegt die Kerbe seitlich; ohne diese Werte klebt Text\r\n     darunter. Unten dasselbe fuer den Strich zum Wischen. */\r\n  padding:var(--r7) calc(var(--r6) + env(safe-area-inset-right, 0px))\r\n          calc(var(--r8) + env(safe-area-inset-bottom, 0px))\r\n          calc(var(--r6) + env(safe-area-inset-left, 0px));\r\n}\r\n/* Auch \"breit\" hat eine Grenze: Auf einem 27-Zoll-Schirm liefen Tabellen\r\n   sonst ueber 2000 Pixel, und das Auge verliert beim Zurueckspringen die\r\n   Zeile. 1680 ist die Breite, ab der nichts mehr dazugewonnen wird. */\r\nmain.breit{\r\n  max-width:1680px; margin-inline:auto;\r\n  padding-left:var(--seitenrand); padding-right:var(--seitenrand);\r\n}\r\nmain.schmal{ max-width:720px; }\r\n\r\nfooter.seite{\r\n  background:var(--navy-tief); color:#C8D6E8;\r\n  padding:var(--r6) calc(var(--seitenrand) + env(safe-area-inset-right, 0px))\r\n          calc(var(--r5) + env(safe-area-inset-bottom, 0px))\r\n          calc(var(--seitenrand) + env(safe-area-inset-left, 0px));\r\n  border-top:3px solid var(--navy);\r\n  font-size:.85rem; text-align:center;\r\n}\r\nfooter.seite a{ color:#98B3D1; }\r\nfooter.seite a:hover{ color:var(--amber-hell); }\r\n.fuss-links{\r\n  display:flex; justify-content:center; gap:var(--r5);\r\n  flex-wrap:wrap; margin-bottom:var(--r4);\r\n}\r\n.fuss-zeile{ margin:var(--r1) 0; }\r\n.fuss-klein{ color:#8FA6C0; font-size:.75rem; margin-top:var(--r3); }\r\n/* Die Urheberzeile der AG. Bewusst abgesetzt: sie ist keine\r\n   Kleingedrucktes-Zeile unter vielen. */\r\n.fuss-urheber{\r\n  margin-top:var(--r4); padding-top:var(--r3);\r\n  border-top:1px solid rgba(152,179,209,.22);\r\n  color:#A8BDD4; font-size:.75rem; line-height:1.7;\r\n}\r\n.fuss-urheber strong{ color:#D8E4F2; font-weight:600; }\r\n\r\n@media (max-width:820px){\r\n  header.seite{\r\n    padding:var(--r3) var(--seitenrand);\r\n    /* Gemessen bei 375 Pixeln: Das Logo ist mit Schriftzug 312 Pixel breit.\r\n       Zusammen mit dem Menue-Knopf passte das nicht in eine Zeile, also\r\n       rutschte der Knopf per flex-wrap in die zweite - dort steht ein\r\n       einzelnes Element bei space-between LINKS. Der Menue-Knopf sass also\r\n       unter dem Logo auf der falschen Seite, und die Kopfleiste war 113\r\n       statt 69 Pixel hoch. Kein Umbruch mehr: Das Logo darf schrumpfen, der\r\n       Knopf bleibt rechts. */\r\n    flex-wrap:nowrap;\r\n  }\r\n  header.seite .marke-logo{ min-width:0; flex:0 1 auto; }\r\n  header.seite .marke-text{ min-width:0; }\r\n  header.seite .marke-text,\r\n  header.seite .marke-motto{\r\n    overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\r\n  }\r\n  .burger{ margin-left:auto; flex-shrink:0; }\r\n  header.seite nav{\r\n    display:none; position:absolute; top:100%; left:0; right:0;\r\n    flex-direction:column; align-items:stretch; gap:2px;\r\n    background:var(--flaeche); padding:var(--r3) var(--r4) var(--r4);\r\n    border-top:2px solid var(--navy); box-shadow:var(--schatten-hoch);\r\n  }\r\n  header.seite.offen nav{ display:flex; }\r\n  header.seite nav a{ font-size:.8rem; padding:var(--r3); }\r\n  header.seite nav a.betont{ text-align:center; margin-top:var(--r2); }\r\n  .thema-schalter{ margin:var(--r3) 0 0; }\r\n  .burger{ display:block; }\r\n  .ticker{ display:none; }\r\n}\r\n\r\n@media (max-width:430px){\r\n  /* Auf dem Telefon traegt das Wappen die Marke. Der Untertitel kostet nur\r\n     Platz, den der Name braucht. */\r\n  header.seite .marke-motto{ display:none; }\r\n  header.seite .marke-logo{ font-size:.98rem; }\r\n  main{ padding:var(--r5) var(--r4) var(--r7); }\r\n}\r\n\r\n/* --- 4. Flaechen -------------------------------------------------------- */\r\n.panel{\r\n  background:var(--flaeche); border:1px solid var(--linie);\r\n  border-radius:var(--rund); padding:var(--r5) var(--r5);\r\n  box-shadow:var(--schatten);\r\n}\r\n.panel.schmal{ padding:var(--r4); }\r\n.panel.betont{ border-left:4px solid var(--amber); }\r\n.panel > h2:first-child, .panel > h3:first-child{ margin-top:0; }\r\n\r\n.panel-kopf{\r\n  display:flex; align-items:flex-start; justify-content:space-between;\r\n  gap:var(--r4); flex-wrap:wrap; margin-bottom:var(--r4);\r\n}\r\n.panel-kopf > div{ min-width:0; }\r\n.panel-kopf h2, .panel-kopf h3{ margin:0; }\r\n.panel-kopf .meta{ margin-top:.15rem; }\r\n.panel-werkzeuge{ display:flex; gap:var(--r2); flex-wrap:wrap; align-items:center; }\r\n\r\n.raster-2{ display:grid; grid-template-columns:1fr 1fr; gap:var(--r5); }\r\n.raster-3{ display:grid; grid-template-columns:repeat(3,1fr); gap:var(--r4); }\r\n.raster-auto{ display:grid; grid-template-columns:repeat(auto-fit,minmax(min(260px, 100%),1fr)); gap:var(--r4); }\r\n.raster-auto-klein{ display:grid; grid-template-columns:repeat(auto-fit,minmax(min(180px, 100%),1fr)); gap:var(--r3); }\r\n.raster-2 > *, .raster-3 > *, .raster-auto > *, .raster-auto-klein > *{ min-width:0; }\r\n@media (max-width:860px){\r\n  .raster-2, .raster-3{ grid-template-columns:1fr; }\r\n}\r\n\r\n.stapel{ display:flex; flex-direction:column; gap:var(--r4); }\r\n.reihe{ display:flex; align-items:center; gap:var(--r3); flex-wrap:wrap; }\r\n.reihe-rechts{ margin-left:auto; }\r\n\r\nul.schlicht{ list-style:none; padding:0; margin:0; }\r\nul.schlicht li{ padding:var(--r2) 0; border-bottom:1px solid var(--linie); }\r\nul.schlicht li:last-child{ border-bottom:none; }\r\n\r\n.karten-seite{ max-width:480px; margin:var(--r5) auto; }\r\n\r\n/* --- 5. Knoepfe --------------------------------------------------------- */\r\n/* Der Rahmen ist durchsichtig statt weg: sonst ist ein Knopf mit Rahmen zwei\r\n   Pixel hoeher als der daneben, und beide sitzen sichtbar versetzt. */\r\nbutton, .btn{\r\n  display:inline-flex; align-items:center; justify-content:center; gap:var(--r2);\r\n  background:var(--navy); color:var(--navy-schrift);\r\n  border:1px solid transparent; border-radius:var(--rund-klein);\r\n  padding:.62rem 1.15rem; min-height:2.6rem;\r\n  font-family:var(--schrift); font-size:.9rem; font-weight:600; line-height:1.3;\r\n  cursor:pointer; text-decoration:none; text-align:center;\r\n  transition:background var(--tempo) ease, border-color var(--tempo) ease,\r\n             color var(--tempo) ease, transform .08s ease;\r\n}\r\nbutton:hover, .btn:hover{ background:var(--amber); color:#fff; text-decoration:none; }\r\nbutton:active, .btn:active{ transform:translateY(1px); }\r\nbutton[disabled], .btn[disabled], button:disabled{\r\n  opacity:.5; cursor:not-allowed; transform:none;\r\n}\r\nbutton[disabled]:hover, button:disabled:hover{ background:var(--navy); }\r\n\r\n.btn-zweit{\r\n  background:var(--flaeche-2); color:var(--text); border-color:var(--linie);\r\n}\r\n.btn-zweit:hover{ background:var(--navy-hauch); color:var(--navy); border-color:var(--navy); }\r\n.btn-still{ background:transparent; color:var(--gedaempft); border-color:transparent; }\r\n.btn-still:hover{ background:var(--flaeche-2); color:var(--text); }\r\n.btn-gefahr{\r\n  background:color-mix(in srgb, var(--rot) 12%, transparent);\r\n  color:var(--rot); border-color:color-mix(in srgb, var(--rot) 38%, transparent);\r\n}\r\n.btn-gefahr:hover{ background:color-mix(in srgb, var(--rot) 24%, transparent); color:var(--rot); }\r\nhtml[data-theme=\"dark\"] .btn-gefahr{\r\n  background:color-mix(in srgb, var(--rot) 14%, var(--flaeche));\r\n}\r\nhtml[data-theme=\"dark\"] .btn-gefahr:hover{\r\n  background:color-mix(in srgb, var(--rot) 26%, var(--flaeche));\r\n}\r\n.btn-gut{\r\n  background:color-mix(in srgb, var(--gruen) 12%, transparent);\r\n  color:var(--gruen); border-color:color-mix(in srgb, var(--gruen) 38%, transparent);\r\n}\r\n.btn-gut:hover{ background:color-mix(in srgb, var(--gruen) 24%, transparent); color:var(--gruen); }\r\nhtml[data-theme=\"dark\"] .btn-gut{\r\n  background:color-mix(in srgb, var(--gruen) 14%, var(--flaeche));\r\n}\r\nhtml[data-theme=\"dark\"] .btn-gut:hover{\r\n  background:color-mix(in srgb, var(--gruen) 26%, var(--flaeche));\r\n}\r\n.btn-klein{ padding:.36rem .7rem; min-height:2.1rem; font-size:.8rem; font-weight:500; }\r\n.btn-breit{ width:100%; }\r\n.btn svg{ width:1.05em; height:1.05em; flex-shrink:0; }\r\n\r\n.knopfzeile{ display:flex; gap:var(--r3); flex-wrap:wrap; align-items:center; }\r\n\r\n/* --- 6. Formulare ------------------------------------------------------- */\r\n/* Ein Satz Regeln fuer alle Eingabefelder. In V1 liefen drei Rhythmen\r\n   nebeneinander und ein Textfeld war 43, ein Auswahlfeld 45 Pixel hoch -\r\n   in einer Zeile stand dadurch nichts auf einer Linie. */\r\nform{ display:flex; flex-direction:column; gap:var(--r4); }\r\nlabel{\r\n  display:flex; flex-direction:column; gap:var(--r1);\r\n  font-size:.82rem; font-weight:600; color:var(--text);\r\n}\r\nlabel > .meta{ font-weight:400; font-size:.75rem; line-height:1.45; }\r\n\r\ninput, select, textarea{\r\n  width:100%; background:var(--flaeche-2); color:var(--text);\r\n  border:1px solid var(--linie); border-radius:var(--rund-klein);\r\n  padding:.58rem .75rem;\r\n  font-family:inherit; font-size:.92rem; line-height:1.45;\r\n  transition:border-color var(--tempo) ease, background var(--tempo) ease;\r\n}\r\ninput:not([type=\"checkbox\"]):not([type=\"radio\"]):not([type=\"file\"]), select{\r\n  min-height:2.6rem;\r\n}\r\ntextarea{ min-height:6.5rem; resize:vertical; }\r\ninput[type=\"file\"]{ background:transparent; border-style:dashed; padding:.5rem .6rem; font-size:.85rem; }\r\ninput[type=\"checkbox\"], input[type=\"radio\"]{\r\n  width:auto; min-height:0; padding:0; margin:0;\r\n  accent-color:var(--navy); cursor:pointer;\r\n}\r\ninput[type=\"color\"]{ padding:.2rem; min-height:2.6rem; cursor:pointer; }\r\ninput:hover, select:hover, textarea:hover{ border-color:var(--amber); }\r\ninput:focus, select:focus, textarea:focus{ border-color:var(--blau); background:var(--flaeche); }\r\ninput[readonly], input[disabled], select[disabled], textarea[disabled]{\r\n  background:var(--flaeche-3); color:var(--gedaempft); cursor:not-allowed;\r\n}\r\n::placeholder{ color:var(--gedaempft-2); opacity:1; }\r\n\r\nselect{\r\n  appearance:none; -webkit-appearance:none; padding-right:2rem;\r\n  background-image:var(--pfeil); background-repeat:no-repeat;\r\n  background-position:right .7rem center; background-size:.7rem;\r\n}\r\nselect[multiple]{ background-image:none; padding-right:.7rem; min-height:8rem; }\r\n\r\n/* Das Raster fuer Formularfelder: ein Feld ist mindestens 250px breit, sonst\r\n   rueckt es in die naechste Zeile. Auf dem Handy steht damit eines unter dem\r\n   anderen, ohne eigene Umbruchregeln. */\r\n.formular{\r\n  display:grid; grid-template-columns:repeat(auto-fit, minmax(min(250px, 100%), 1fr));\r\n  gap:var(--r4); align-items:end;\r\n}\r\n.formular > *{ grid-column:1 / -1; }\r\n.formular > label{ grid-column:auto; }\r\n.formular > label:has(textarea), .formular > label.voll{ grid-column:1 / -1; }\r\n.formular > label:has(input[type=\"checkbox\"]){\r\n  flex-direction:row; align-items:center; gap:var(--r2); font-weight:500;\r\n}\r\n/* Zwei Felder nebeneinander - aber nur, wenn zwei nebeneinander passen.\r\n   Mit festen \"1fr 1fr\" bleiben es auch auf einem 375er-Schirm zwei Spalten,\r\n   und weil ein Datumsfeld sich nicht beliebig schmal machen laesst, schob\r\n   das Paar 18 Pixel ueber den rechten Rand hinaus. minmax(min(...)) laesst\r\n   es umbrechen, min-width:0 erlaubt den Feldern zu schrumpfen. */\r\n.formular > .feldpaar{\r\n  grid-column:auto; display:grid;\r\n  grid-template-columns:repeat(auto-fit, minmax(min(11rem, 100%), 1fr));\r\n  gap:var(--r3); align-items:end;\r\n}\r\n.formular > .feldpaar > *{ min-width:0; }\r\ninput, select, textarea{ max-width:100%; }\r\n.formular > .formular-fuss{\r\n  display:flex; gap:var(--r3); flex-wrap:wrap; align-items:center;\r\n  margin-top:var(--r1); padding-top:var(--r4); border-top:1px solid var(--linie);\r\n}\r\n\r\n.haken{\r\n  display:flex; flex-direction:row; align-items:flex-start; gap:var(--r2);\r\n  padding:var(--r2); border-radius:var(--rund-klein);\r\n  font-size:.87rem; font-weight:400; cursor:pointer; margin:0;\r\n}\r\n.haken:hover{ background:var(--flaeche-2); }\r\n.haken input{ margin-top:.2rem; flex-shrink:0; }\r\n.haken:has(input:checked){ background:var(--navy-hauch); }\r\n.haken:has(input:checked) > span:first-of-type{ color:var(--navy); font-weight:500; }\r\n\r\n.zeichenzahl{ align-self:flex-end; font-size:.72rem; color:var(--gedaempft); }\r\n.zeichen-knapp{ color:var(--amber); font-weight:600; }\r\n\r\n/* --- 7. Meldungen ------------------------------------------------------- */\r\n/* Rueckmeldungen standen in V1 als nackte gruene oder rote Zeile im Text und\r\n   liessen sich leicht uebersehen. Als abgesetzter Kasten sind sie sofort als\r\n   Antwort des Systems erkennbar. */\r\n.meldung{\r\n  display:flex; align-items:flex-start; gap:var(--r3);\r\n  padding:var(--r3) var(--r4); margin:var(--r3) 0;\r\n  border-radius:var(--rund-klein); border-left:3px solid currentColor;\r\n  font-size:.89rem; line-height:1.55;\r\n}\r\n.meldung::before{ font-weight:700; flex-shrink:0; line-height:1.55; }\r\n.meldung > div{ min-width:0; }\r\n.meldung p{ margin:0; }\r\n.meldung p + p{ margin-top:var(--r2); }\r\n.meldung-gut{ color:var(--gruen); background:color-mix(in srgb, var(--gruen) 24%, var(--flaeche)); }\r\n.meldung-gut::before{ content:\"\u2713\"; }\r\n.meldung-fehler{ color:var(--rot); background:color-mix(in srgb, var(--rot) 22%, var(--flaeche)); }\r\n.meldung-fehler::before{ content:\"!\"; }\r\n.meldung-warnung{ color:var(--amber); background:color-mix(in srgb, var(--amber) 25%, var(--flaeche)); }\r\n.meldung-warnung::before{ content:\"!\"; }\r\n.meldung-info{ color:var(--blau); background:color-mix(in srgb, var(--blau) 22%, var(--flaeche)); }\r\n.meldung-info::before{ content:\"i\"; }\r\n.meldung strong{ color:inherit; }\r\n\r\n/* Auf dunklem Grund taugt der Bauplan \"Akzentfarbe mit 10 Prozent Deckkraft\r\n   ueber dem Seitengrund\" nicht: Zehn Prozent Farbe ueber Fast-Schwarz heben\r\n   die Flaeche zwar an, tragen aber kaum Farbe hinein. Gemessen kam dabei\r\n   heraus - Warnung #24252B, Fehler #201D2C, Erfolg #152630: drei schmutzige\r\n   Grautoene, die alle gleich aussehen und keiner nach seiner Bedeutung.\r\n   Deshalb hier andersherum gemischt: eine ordentliche Portion Akzent IN die\r\n   Flaeche statt ein Hauch Akzent UEBER den Grund. Das Ergebnis liegt in der\r\n   Helligkeit der uebrigen Kaesten und hat einen erkennbaren Farbton. */\r\nhtml[data-theme=\"dark\"] .meldung{\r\n  /* Nachgerechnet: Ein warmer Ton in einer blaugrauen Flaeche hebt sich\r\n     selbst auf. Bernstein ergab bei 15 Prozent ein reines Grau (#373639),\r\n     und erst bei 30 Prozent kam Farbe heraus - dann aber Oliv, also genau\r\n     der Matsch, um den es hier geht. Rot lief ins Graulila.\r\n     Deshalb im Dunkeln fuer ALLE vier dieselbe ruhige Flaeche. Die\r\n     Bedeutung tragen die Dinge, die Farbe auch wirklich halten koennen:\r\n     der Rand links, das Zeichen davor und die fette Zeile. Das ist\r\n     ausserdem einheitlich - vier Kaesten, die sich nur in der Kante\r\n     unterscheiden, liest man schneller als vier verschieden schmutzige. */\r\n  background:var(--flaeche-2);\r\n  border-left-width:4px;\r\n}\r\n/* Die Schrift im Kasten nimmt die Akzentfarbe an. Auf der nun helleren,\r\n   getoenten Flaeche liest sich der Fliesstext besser in der normalen\r\n   Textfarbe - die Farbe tragen Rand, Zeichen und Ueberschrift. */\r\nhtml[data-theme=\"dark\"] .meldung p{ color:var(--text); }\r\n/* Der Text bleibt lesbar, nur das Zeichen und der Rand tragen die Farbe. */\r\n.meldung > div, .meldung > p{ color:var(--text); }\r\nhtml[data-theme=\"dark\"] .meldung-gut{\r\n  background:color-mix(in srgb, var(--gruen) 32%, var(--flaeche-2));\r\n}\r\nhtml[data-theme=\"dark\"] .meldung-fehler{\r\n  background:color-mix(in srgb, var(--rot) 30%, var(--flaeche-2));\r\n}\r\nhtml[data-theme=\"dark\"] .meldung-warnung{\r\n  background:color-mix(in srgb, var(--amber) 32%, var(--flaeche-2));\r\n}\r\nhtml[data-theme=\"dark\"] .meldung-info{\r\n  background:color-mix(in srgb, var(--blau) 30%, var(--flaeche-2));\r\n}\r\n\r\n.fehler{ color:var(--rot); }\r\n.gut{ color:var(--gruen); }\r\n.warnung{ color:var(--amber); }\r\n\r\n/* --- 8. Marken (Status, Prioritaet, Abteilung) -------------------------- */\r\n.marke{\r\n  display:inline-flex; align-items:center; gap:.3rem;\r\n  padding:.15rem .55rem; border-radius:var(--rund-voll);\r\n  border:1px solid transparent; background:var(--flaeche-2);\r\n  font-size:.73rem; font-weight:600; line-height:1.5;\r\n  white-space:nowrap; vertical-align:middle;\r\n  --marke:var(--gedaempft);\r\n}\r\n.marke + .marke{ margin-left:.3rem; }\r\n.marke[class*=\"zustand-\"], .marke[class*=\"rang-\"], .marke.abteilung{\r\n  color:color-mix(in srgb, var(--marke) 62%, #000);\r\n  background:color-mix(in srgb, var(--marke) 12%, transparent);\r\n  border-color:color-mix(in srgb, var(--marke) 32%, transparent);\r\n}\r\n/* Auf dunklem Grund waere abgedunkelte Schrift unlesbar - dort der reine\r\n   Akzentton. Fuer Abteilungen umgekehrt aufhellen: fuer sie ist genau EINE\r\n   Farbe hinterlegt, und die ist auf hellen Grund ausgelegt. */\r\nhtml[data-theme=\"dark\"] .marke[class*=\"zustand-\"],\r\nhtml[data-theme=\"dark\"] .marke[class*=\"rang-\"]{ color:var(--marke); }\r\n/* Auch hier: Akzent in die Flaeche, nicht ueber den Grund. Sonst sind alle\r\n   Abzeichen derselbe dunkle Fleck und nur die Schrift unterscheidet sie. */\r\nhtml[data-theme=\"dark\"] .marke[class*=\"zustand-\"],\r\nhtml[data-theme=\"dark\"] .marke[class*=\"rang-\"],\r\nhtml[data-theme=\"dark\"] .marke.abteilung{\r\n  background:color-mix(in srgb, var(--marke) 18%, var(--flaeche));\r\n  border-color:color-mix(in srgb, var(--marke) 42%, transparent);\r\n}\r\nhtml[data-theme=\"dark\"] .marke.abteilung{\r\n  color:color-mix(in srgb, var(--marke) 45%, #FFFFFF);\r\n}\r\n\r\n.zustand-erledigt, .zustand-angenommen, .zustand-aktiv,\r\n.zustand-veroeffentlicht, .zustand-abgeschlossen, .zustand-gesendet{ --marke:var(--gruen); }\r\n.zustand-abgelehnt, .zustand-inaktiv, .zustand-fehler,\r\n.zustand-ueberfaellig{ --marke:var(--rot); }\r\n.zustand-offen, .zustand-neu, .zustand-in_pruefung,\r\n.zustand-in_bearbeitung, .zustand-in_arbeit, .zustand-laufend{ --marke:var(--amber); }\r\n.zustand-geplant, .zustand-planung{ --marke:var(--blau); }\r\n.zustand-idee, .zustand-beantwortet{ --marke:var(--gedaempft); }\r\n.rang-hoch{ --marke:var(--rot); }\r\n.rang-mittel{ --marke:var(--amber); }\r\n.rang-niedrig{ --marke:var(--gedaempft); }\r\n\r\n/* \"Ueberfaellig\" ist die dringendste Meldung im System. Im Dunkelmodus ist\r\n   --rot ein heller Ton fuer Text; als Flaeche mit weisser Schrift kaeme er\r\n   nur auf 3,1:1. Die Schriftfarbe kommt deshalb aus dem Farbschema. */\r\n.marke-alarm{ background:var(--rot); color:var(--kontrast); border-color:var(--rot); }\r\n.zaehler{\r\n  display:inline-flex; align-items:center; justify-content:center;\r\n  min-width:1.35rem; height:1.35rem; padding:0 .35rem;\r\n  border-radius:var(--rund-voll); background:var(--amber); color:#fff;\r\n  font-family:var(--schrift-mono); font-size:.7rem; font-weight:600;\r\n}\r\n\r\n/* --- 9. Tabellen -------------------------------------------------------- */\r\n.tabelle-rahmen{\r\n  overflow-x:auto; border-radius:var(--rund); border:1px solid var(--linie);\r\n  background:var(--flaeche);\r\n}\r\n.panel > .tabelle-rahmen{ border:none; border-radius:0; }\r\ntable{ width:100%; border-collapse:collapse; font-size:.9rem; }\r\nth, td{ padding:.62rem .85rem; text-align:left; vertical-align:middle; }\r\nth{\r\n  font-family:var(--schrift-mono); font-size:.67rem; font-weight:600;\r\n  letter-spacing:.08em; text-transform:uppercase; color:var(--gedaempft);\r\n  background:var(--flaeche-2); border-bottom:2px solid var(--linie);\r\n  white-space:nowrap; position:sticky; top:0; z-index:1;\r\n}\r\ntd{ border-bottom:1px solid var(--linie); }\r\ntbody tr:last-child td{ border-bottom:none; }\r\n/* Zebra nur bei langen Listen - dort hilft es beim Zeilehalten. */\r\ntbody tr:nth-child(even){ background:color-mix(in srgb, var(--flaeche-2) 42%, transparent); }\r\ntbody tr:hover, tbody tr:nth-child(even):hover{ background:var(--flaeche-2); }\r\ntd.rechts, th.rechts{ text-align:right; }\r\ntd.zahl{ font-family:var(--schrift-mono); text-align:right; font-variant-numeric:tabular-nums; }\r\n\r\n.leer{\r\n  padding:var(--r6) var(--r4); text-align:center; color:var(--gedaempft);\r\n}\r\n.leer-zeichen{ font-size:2rem; display:block; margin-bottom:var(--r2); opacity:.5; }\r\n.leer strong{ display:block; color:var(--text); margin-bottom:var(--r1); }\r\n\r\n/* --- 10. Aufklapper ----------------------------------------------------- */\r\ndetails.block{\r\n  border:1px solid var(--linie); border-radius:var(--rund);\r\n  background:var(--flaeche); overflow:hidden;\r\n}\r\ndetails.block > summary{\r\n  list-style:none; cursor:pointer; padding:var(--r3) var(--r4);\r\n  font-weight:600; font-size:.9rem; color:var(--navy);\r\n  display:flex; align-items:center; gap:var(--r2);\r\n}\r\ndetails.block > summary::-webkit-details-marker{ display:none; }\r\ndetails.block > summary::before{\r\n  content:\"\u25b8\"; font-size:.7rem; transition:transform var(--tempo) ease;\r\n}\r\ndetails.block[open] > summary::before{ transform:rotate(90deg); }\r\ndetails.block > summary:hover{ background:var(--flaeche-2); }\r\ndetails.block[open] > summary{ border-bottom:1px solid var(--linie); background:var(--flaeche-2); }\r\n.aufklapp-inhalt{ padding:var(--r4); }\r\n\r\n/* --- 11. Fortschritt ---------------------------------------------------- */\r\n.balken{\r\n  width:100%; height:.6rem; background:var(--flaeche-3);\r\n  border-radius:var(--rund-voll); overflow:hidden;\r\n}\r\n.balken > span{\r\n  display:block; height:100%; border-radius:var(--rund-voll);\r\n  background:var(--gruen); transition:width .3s ease;\r\n}\r\n.balken.blau > span{ background:var(--blau); }\r\n.balken.amber > span{ background:var(--amber); }\r\n.balken.rot > span{ background:var(--rot); }\r\n\r\n/* --- 12. Ladeplatzhalter ------------------------------------------------ */\r\n.platzhalter{\r\n  border-radius:var(--rund-klein);\r\n  background:linear-gradient(90deg, var(--flaeche-2) 25%, var(--linie) 37%, var(--flaeche-2) 63%);\r\n  background-size:400% 100%; animation:schimmer 1.4s ease-in-out infinite;\r\n}\r\n.platzhalter-block{ height:110px; border-radius:var(--rund); }\r\n@keyframes schimmer{ 0%{ background-position:100% 50%; } 100%{ background-position:0 50%; } }\r\n\r\n/* htmx: waehrend eine Anfrage laeuft, tritt der Bereich sichtbar zurueck.\r\n   Ohne das wirkt jeder Klick wie ohne Reaktion, bis die Antwort da ist. */\r\n.htmx-request, .htmx-request *{ cursor:progress; }\r\n#tab-inhalt.htmx-request{ opacity:.55; transition:opacity .12s ease; }\r\n\r\nbody.dashboard-laedt::before{\r\n  content:\"\"; position:fixed; z-index:9999; left:0; top:0; height:3px;\r\n  width:35%; background:var(--akzent, #2563eb);\r\n  box-shadow:0 0 10px var(--akzent, #2563eb);\r\n  animation:dashboard-ladebalken 1.1s ease-in-out infinite alternate;\r\n}\r\nbody.dashboard-laedt #tab-inhalt{\r\n  transition:opacity .12s ease;\r\n}\r\nbody.dashboard-laedt .htmx-indicator{\r\n  opacity:1;\r\n}\r\n.such-ziel{\r\n  outline:3px solid var(--akzent, #2563eb);\r\n  outline-offset:4px;\r\n  background:color-mix(in srgb, var(--akzent, #2563eb) 16%, transparent);\r\n}\r\n@keyframes dashboard-ladebalken{\r\n  from{ transform:translateX(0); }\r\n  to{ transform:translateX(185vw); }\r\n}\r\n\r\n/* --- 13. Kleinteile ----------------------------------------------------- */\r\n.kennzahlen{\r\n  display:grid; grid-template-columns:repeat(auto-fit,minmax(min(140px, 100%),1fr));\r\n  gap:var(--r3);\r\n}\r\n.kennzahl{\r\n  background:var(--flaeche-2); border:1px solid var(--linie);\r\n  border-radius:var(--rund-klein); padding:var(--r3) var(--r4);\r\n  display:flex; flex-direction:column; gap:.1rem; min-width:0;\r\n}\r\n.kennzahl-wert{\r\n  font-family:var(--schrift-titel); font-size:1.7rem; line-height:1.1;\r\n  color:var(--navy); font-variant-numeric:tabular-nums;\r\n}\r\n.kennzahl-name{ font-size:.76rem; color:var(--gedaempft); }\r\n.kennzahl-warnung{ border-color:var(--rot); }\r\n.kennzahl-warnung .kennzahl-wert{ color:var(--rot); }\r\n.kennzahl-gut .kennzahl-wert{ color:var(--gruen); }\r\n\r\n.trenner{\r\n  margin:var(--r6) 0 var(--r4); padding-top:var(--r5);\r\n  border-top:2px solid var(--linie);\r\n}\r\n.trenner h2{ margin:0 0 .15rem; font-size:1.2rem; color:var(--gedaempft); }\r\n\r\n/* --- In ein Passwortfeld hineinsehen -------------------------------------\r\n   Gemeldet: \"richtiges Passwort, trotzdem falsch\". Meist steht im Feld ein\r\n   alter Wert aus dem Passwortspeicher des Browsers, und man sieht nur\r\n   Punkte. Der Knopf sitzt im Feld, damit klar ist, wozu er gehoert. */\r\n.feld-mit-auge{ position:relative; display:block; }\r\n.feld-mit-auge input{ padding-right:5.6rem; }\r\n.auge{\r\n  position:absolute; right:.35rem; top:50%; transform:translateY(-50%);\r\n  min-height:0; padding:.3rem .55rem; border:1px solid var(--linie);\r\n  border-radius:var(--rund-klein); background:var(--flaeche-2);\r\n  color:var(--gedaempft); font-family:var(--schrift-mono);\r\n  font-size:.68rem; letter-spacing:.04em; text-transform:uppercase;\r\n  cursor:pointer;\r\n}\r\n.auge:hover{ color:var(--text); border-color:var(--linie-stark); }\r\n/* Auf dem Handy gross genug zum Treffen. */\r\n@media (pointer:coarse){ .auge{ padding:.45rem .6rem; } }\r\n\n/* --- stil/website.css --- */\n/* ===========================================================================\r\n   Oeffentliche Seite - Startseite, Bewerbung, Quiz, Rechtstexte\r\n   ========================================================================= */\r\n\r\n/* Abstand zwischen den Abschnitten: enger als vorher (war --r8). Die Kapitel\r\n   sind jetzt am Amber-Strich vor der Zeile zu erkennen; dafuer braucht es\r\n   nicht mehr so viel Leerraum, und die Seite wird deutlich kuerzer. */\r\n.abschnitt{ margin-bottom:var(--r7); scroll-margin-top:6rem; }\r\n.abschnitt:last-child{ margin-bottom:var(--r6); }\r\n\r\n/* Kapitelmarke: ein kurzer Strich vor der kleinen \u00dcberschrift. Er sagt dem\r\n   Auge beim Scrollen \"hier faengt etwas Neues an\" - vorher unterschieden\r\n   sich die Abschnitte nur durch Abstand. */\r\n.abschnitt .hut::before{\r\n  content:\"\"; display:inline-block; vertical-align:middle;\r\n  width:1.7rem; height:2px; margin-right:.55rem;\r\n  background:var(--amber); border-radius:2px;\r\n}\r\n/* Im Aufmacher nicht: dort ist die Zeile die Herkunftsangabe, kein Kapitel.\r\n   Steht bewusst danach und mit gleicher Staerke - die spaetere Regel gewinnt. */\r\n.aufmacher .hut::before{ display:none; }\r\n\r\n/* Ueberschriften der Abschnitte etwas groesser - der Unterschied zwischen\r\n   Kapitelname und Fliesstext war zu klein. */\r\n.abschnitt > h2, .abschnitt > div > h2{ margin-bottom:var(--r3); }\r\n\r\n/* --- Kopfbereich ---------------------------------------------------------\r\n   Der Aufmacher war genauso hoch wie jeder andere Abschnitt - die Seite las\r\n   sich als neun gleich grosse Bloecke hintereinander, ohne Anfang. Jetzt\r\n   traegt er sichtbar mehr Gewicht: Text links, Wappen rechts, darunter die\r\n   vier Angaben zum Ueberfliegen. */\r\n.aufmacher{\r\n  display:grid; grid-template-columns:minmax(0,1.25fr) minmax(0,.75fr);\r\n  gap:var(--r6); align-items:center;\r\n  padding:var(--r7) 0 var(--r6);\r\n  margin-bottom:var(--r5);\r\n}\r\n.aufmacher h1{\r\n  max-width:20ch; font-size:clamp(2rem, 1.2rem + 3.2vw, 3.1rem);\r\n  background:linear-gradient(100deg, var(--navy) 35%, var(--amber) 82%);\r\n  -webkit-background-clip:text; background-clip:text; color:transparent;\r\n}\r\nhtml[data-theme=\"dark\"] .aufmacher h1{\r\n  /* Im Hellen laeuft die Ueberschrift von Marineblau nach Bernstein - zwei\r\n     dunkle, satte Toene, dazwischen nichts Auffaelliges. Im Dunkeln sind\r\n     dieselben Variablen HELLBLAU und ORANGE, und ein Verlauf zwischen\r\n     hellblau und orange geht mitten durch Grau und Khaki. Die Ueberschrift\r\n     zerfiel dadurch in drei Farben und sah aus wie ein Darstellungsfehler.\r\n     Hier deshalb ein Verlauf innerhalb einer Familie: von fast weiss nach\r\n     hellblau. Kein Umweg ueber tr\u00fcbe Zwischentoene. */\r\n  background:linear-gradient(100deg, var(--text-stark) 20%, var(--navy) 92%);\r\n  -webkit-background-clip:text; background-clip:text;\r\n  /* Kein text-shadow: Bei durchsichtigem Text liegt er hinter den Buchstaben\r\n     und macht daraus einen Schmierfleck. */\r\n}\r\n.aufmacher-motto{\r\n  font-family:var(--schrift-mono); font-size:.86rem; letter-spacing:.02em;\r\n  color:var(--amber); margin:.1rem 0 var(--r4);\r\n}\r\n.aufmacher .fuehrung{\r\n  font-size:1.03rem; color:var(--gedaempft); max-width:52ch; line-height:1.8;\r\n}\r\n.aufmacher .knopfzeile{ margin-top:var(--r5); }\r\n\r\n/* Das Wappen mit einem warmen Schein dahinter - sonst schwebt es im Nichts. */\r\n.aufmacher-bild{ position:relative; display:flex; justify-content:center; }\r\n.aufmacher-bild::before{\r\n  content:\"\"; position:absolute; inset:-12% -6%;\r\n  background:radial-gradient(circle at 50% 45%,\r\n             var(--amber-hauch) 0%, transparent 68%);\r\n  z-index:0;\r\n}\r\n.aufmacher-bild img{\r\n  position:relative; z-index:1;\r\n  width:100%; max-width:300px; height:auto;\r\n  filter:drop-shadow(0 18px 34px rgba(8,15,26,.28));\r\n}\r\nhtml[data-theme=\"dark\"] .aufmacher-bild img{\r\n  /* Gross genug fuer eine sichtbare Kante plus einen Hauch Streulicht - das\r\n     hebt das Wappen von der Nacht ab, ohne dass es leuchtet. Siehe die\r\n     Erklaerung zu img.wappen in basis.css. */\r\n  filter:\r\n    drop-shadow(0 0 2px rgba(255,255,255,.9))\r\n    drop-shadow(0 0 2px rgba(255,255,255,.9))\r\n    drop-shadow(0 0 14px rgba(255,255,255,.18))\r\n    drop-shadow(0 18px 40px rgba(0,0,0,.55));\r\n}\r\nhtml[data-theme=\"dark\"] .aufmacher-bild::before{\r\n  /* Der warme Schein wird auf dunklem Grund zu einem gelben Fleck hinter dem\r\n     weissen Saum. Kuehler und schwaecher passt er zur Nacht. */\r\n  background:radial-gradient(circle at 50% 45%,\r\n             rgba(150,180,225,.16) 0%, transparent 66%);\r\n}\r\n@media (max-width:860px){\r\n  .aufmacher{ grid-template-columns:1fr; padding-top:var(--r5); }\r\n  /* Auf dem Tablet zuerst der Satz, dann das Bild - und kleiner. */\r\n  .aufmacher-bild{ order:2; }\r\n  .aufmacher-bild img{ max-width:190px; }\r\n}\r\n@media (max-width:640px){\r\n  /* Auf dem Handy ganz weg: Das Wappen steht schon in der Kopfzeile, und\r\n     hier kostet es eine Viertel Bildschirmlaenge, bevor die vier Angaben\r\n     kommen. Schmuck darf nicht vor der Auskunft stehen. */\r\n  .aufmacher-bild{ display:none; }\r\n  .aufmacher{ padding-bottom:var(--r4); margin-bottom:var(--r4); }\r\n}\r\n\r\n/* --- Die vier Angaben unter dem Aufmacher -------------------------------- */\r\n/* 150px als Untergrenze: damit stehen auch auf einem 375er-Schirm noch zwei\r\n   nebeneinander statt vier untereinander - vier gestapelte Kaesten waeren auf\r\n   dem Handy eine halbe Bildschirmlaenge, bevor der Text ueberhaupt anfaengt. */\r\n.fakten{\r\n  list-style:none; margin:0 0 var(--r7); padding:0;\r\n  display:grid; grid-template-columns:repeat(auto-fit, minmax(min(150px,100%),1fr));\r\n  gap:var(--r3);\r\n}\r\n.fakten li{\r\n  display:flex; flex-direction:column; gap:.15rem;\r\n  padding:var(--r4);\r\n  background:var(--flaeche); border:1px solid var(--linie);\r\n  border-top:3px solid var(--amber);\r\n  border-radius:var(--rund);\r\n}\r\n/* Vier kraeftige Balken nebeneinander sind auf hellem Grund eine Reihe, auf\r\n   dunklem eine Leuchtschrift. Duenner und gedaempft reicht: Die Karten\r\n   heben sich im Dunkeln ohnehin schon durch ihre Flaeche ab. */\r\nhtml[data-theme=\"dark\"] .fakten li{\r\n  border-top-width:2px;\r\n  border-top-color:color-mix(in srgb, var(--amber) 85%, transparent);\r\n}\r\n@media (max-width:520px){\r\n  .fakten li{ padding:var(--r3); }\r\n  .fakten strong{ font-size:.95rem; }\r\n  .fakten span{ font-size:.8rem; }\r\n}\r\n.fakten strong{\r\n  font-family:var(--schrift-titel); font-size:1.02rem; color:var(--text-stark);\r\n}\r\n.fakten span{ font-size:.86rem; color:var(--gedaempft); line-height:1.5; }\r\n\r\n\r\n/* --- Was du mitnimmst ---------------------------------------------------- */\r\n.vorteile-kasten{\r\n  background:var(--amber-hauch); padding:var(--r6);\r\n  border-radius:var(--rund); border:1px solid color-mix(in srgb, var(--amber) 22%, transparent);\r\n}\r\n/* Bernstein mit 13 Prozent Deckkraft ueber hellem Papier ist ein warmer\r\n   Hauch. Ueber dunklem Marineblau ist es Braun - und daneben stehen gruene\r\n   Haken und blaue Schrift. Im Dunkeln deshalb eine ruhige, leicht erhoehte\r\n   Flaeche; die Farbe traegt allein die Ueberschrift. */\r\nhtml[data-theme=\"dark\"] .vorteile-kasten{\r\n  background:var(--flaeche-2);\r\n  border-color:var(--linie);\r\n}\r\n.vorteile-kasten h3{ margin-top:0; color:var(--amber); }\r\nhtml[data-theme=\"dark\"] .vorteile-kasten h3{ color:var(--amber-hell); }\r\n.vorteile-liste{ list-style:none; padding:0; margin:0; }\r\n.vorteile-liste li{\r\n  display:flex; gap:var(--r3); align-items:flex-start;\r\n  padding:var(--r2) 0; color:var(--text); font-size:.94rem;\r\n}\r\n.vorteile-liste li::before{\r\n  content:\"\u2713\"; color:var(--gruen); font-weight:700; flex-shrink:0;\r\n}\r\n\r\n/* --- Halbjahre ----------------------------------------------------------- */\r\n.halbjahr{ position:relative; padding-left:4.2rem; border-left:4px solid var(--navy); }\r\n.halbjahr.zwei{ border-left-color:var(--amber); }\r\n.halbjahr h3{ margin-top:0; }\r\n.halbjahr-nummer{\r\n  position:absolute; left:1.4rem; top:1.3rem;\r\n  font-family:var(--schrift-titel); font-size:2.1rem; font-weight:700;\r\n  line-height:1; color:var(--navy); opacity:.22;\r\n}\r\n.halbjahr.zwei .halbjahr-nummer{ color:var(--amber); opacity:.35; }\r\n.halbjahr-fazit{ margin:var(--r5) 0 0; color:var(--gedaempft); font-size:.94rem; }\r\n@media (max-width:720px){\r\n  .halbjahr{ padding-left:var(--r5); }\r\n  .halbjahr-nummer{ position:static; display:block; margin-bottom:.2rem; font-size:1.6rem; }\r\n}\r\n\r\n/* --- Unsere Arbeit (aus der Datenbank) ----------------------------------- */\r\n/* Die Karten stehen nicht mehr im Quelltext, sondern in der Tabelle\r\n   seiten_inhalte und lassen sich im Dashboard pflegen. Farbe und Zeichen\r\n   kommen je Karte mit - deshalb --karte als Variable am Element. */\r\n.arbeit-karte{\r\n  border-left:4px solid var(--karte, var(--navy));\r\n  padding-left:var(--r5); position:relative;\r\n  transition:transform var(--tempo) ease, box-shadow var(--tempo) ease;\r\n}\r\n.arbeit-karte:hover{ transform:translateY(-2px); box-shadow:var(--schatten-hoch); }\r\n.arbeit-karte h3{ margin-top:0; display:flex; align-items:center; gap:var(--r2); }\r\n.arbeit-zeichen{ font-size:1.15rem; line-height:1; }\r\n.arbeit-karte p{ margin:0; color:var(--gedaempft); }\r\n.arbeit-karte img,.portfolio-karte img{\r\n  width:100%; max-height:15rem; object-fit:cover; border-radius:var(--r2);\r\n  margin-bottom:var(--r3);\r\n}\r\n\r\n/* --- Stufen -------------------------------------------------------------- */\r\n.stufen{ list-style:none; counter-reset:stufe; margin:var(--r6) 0 0; padding:0 0 0 .2rem; position:relative; }\r\n.stufen::before{\r\n  content:\"\"; position:absolute; left:1.05rem; top:.9rem; bottom:.9rem;\r\n  width:2px; background:var(--linie);\r\n}\r\n.stufen li{\r\n  counter-increment:stufe; position:relative;\r\n  padding:0 0 var(--r5) 3.2rem; display:flex; flex-direction:column; gap:.15rem;\r\n}\r\n.stufen li:last-child{ padding-bottom:0; }\r\n.stufen li::before{\r\n  content:counter(stufe); position:absolute; left:0; top:-.1rem;\r\n  width:2.2rem; height:2.2rem; border-radius:50%;\r\n  display:flex; align-items:center; justify-content:center;\r\n  background:var(--flaeche); border:2px solid var(--navy); color:var(--navy);\r\n  font-family:var(--schrift-mono); font-size:.85rem; font-weight:600;\r\n}\r\n.stufen strong{ font-family:var(--schrift-titel); font-size:1.02rem; }\r\n.stufen span{ color:var(--gedaempft); }\r\n.stufen-fazit{ margin:var(--r5) 0 0; color:var(--gedaempft); font-size:.94rem; }\r\n\r\n/* --- Aufrufe ------------------------------------------------------------- */\r\n.aufruf{\r\n  background:linear-gradient(135deg, var(--amber-hauch) 0%, var(--navy-hauch) 100%);\r\n  padding:var(--r7) var(--r6); border-radius:var(--rund);\r\n  border:1px solid color-mix(in srgb, var(--amber) 16%, transparent);\r\n  text-align:center;\r\n}\r\n/* Warm nach kalt ueber Dunkelblau ergibt in der Mitte wieder Braun. */\r\nhtml[data-theme=\"dark\"] .aufruf{\r\n  background:var(--flaeche-2);\r\n  border-color:var(--linie);\r\n}\r\n.aufruf > div{ max-width:600px; margin:0 auto; }\r\n.aufruf h2{ color:var(--amber); }\r\n.aufruf .btn{ margin-top:var(--r4); }\r\n\r\n.quiz-anriss{\r\n  display:flex; align-items:center; justify-content:space-between;\r\n  gap:var(--r5); flex-wrap:wrap; border-left:4px solid var(--amber);\r\n}\r\n.quiz-anriss > div{ flex:1 1 300px; }\r\n.quiz-anriss h2{ margin-top:0; }\r\n\r\n/* --- Kontakt ------------------------------------------------------------- */\r\n.kontakt-formular{ display:flex; flex-direction:column; gap:var(--r4); }\r\n\r\n/* --- Quiz ---------------------------------------------------------------- */\r\n.quiz-fortschritt{ margin-bottom:var(--r5); }\r\n.quiz-fortschritt-kopf{\r\n  display:flex; justify-content:space-between; font-family:var(--schrift-mono);\r\n  font-size:.74rem; color:var(--gedaempft); margin-bottom:var(--r2);\r\n}\r\n.quiz-frage-text{ font-size:1.2rem; margin-bottom:var(--r4); }\r\n.quiz-optionen{ display:flex; flex-direction:column; gap:var(--r2); }\r\n.quiz-option{\r\n  display:flex; align-items:center; gap:var(--r3); width:100%;\r\n  text-align:left; justify-content:flex-start;\r\n  background:var(--flaeche-2); color:var(--text); border:1px solid var(--linie);\r\n  padding:var(--r3) var(--r4); font-weight:500; min-height:3rem;\r\n}\r\n.quiz-option:hover:not(:disabled){\r\n  background:var(--navy-hauch); color:var(--navy); border-color:var(--navy);\r\n}\r\n.quiz-marke{\r\n  display:inline-flex; align-items:center; justify-content:center;\r\n  width:1.7rem; height:1.7rem; flex-shrink:0; border-radius:50%;\r\n  background:var(--flaeche); border:1px solid var(--linie);\r\n  font-family:var(--schrift-mono); font-size:.8rem;\r\n}\r\n.quiz-option.richtig{\r\n  background:color-mix(in srgb, var(--gruen) 14%, transparent);\r\n  border-color:var(--gruen); color:var(--gruen); opacity:1;\r\n}\r\n.quiz-option.falsch{\r\n  background:color-mix(in srgb, var(--rot) 14%, transparent);\r\n  border-color:var(--rot); color:var(--rot); opacity:1;\r\n}\r\n.quiz-option:disabled{ cursor:default; }\r\nhtml[data-theme=\"dark\"] .quiz-option.richtig{\r\n  background:color-mix(in srgb, var(--gruen) 18%, var(--flaeche));\r\n}\r\nhtml[data-theme=\"dark\"] .quiz-option.falsch{\r\n  background:color-mix(in srgb, var(--rot) 18%, var(--flaeche));\r\n}\r\n.quiz-rueckmeldung{ margin-top:var(--r4); }\r\n.quiz-fuss{ margin-top:var(--r4); display:flex; justify-content:flex-end; }\r\n.quiz-punktzahl{\r\n  font-family:var(--schrift-titel); font-size:2.6rem; line-height:1;\r\n  color:var(--navy); margin:var(--r2) 0;\r\n}\r\n.quiz-bilanz{ list-style:none; padding:0; margin:var(--r4) 0; }\r\n.quiz-bilanz li{\r\n  display:flex; gap:var(--r3); align-items:flex-start;\r\n  padding:var(--r3) 0; border-bottom:1px solid var(--linie); font-size:.9rem;\r\n}\r\n.quiz-bilanz li:last-child{ border-bottom:none; }\r\n.quiz-bilanz-zeichen{ font-weight:700; flex-shrink:0; }\r\n.quiz-bilanz li.gut .quiz-bilanz-zeichen{ color:var(--gruen); }\r\n.quiz-bilanz li.schlecht .quiz-bilanz-zeichen{ color:var(--rot); }\r\n.quiz-bilanz-loesung{ display:block; color:var(--gedaempft); font-size:.85rem; }\r\n.quiz-ergebnis-knoepfe{ display:flex; gap:var(--r3); flex-wrap:wrap; margin-top:var(--r5); }\r\n\r\n/* --- Rechtstexte --------------------------------------------------------- */\r\n.rechtstext h2{ margin-top:var(--r6); font-size:1.25rem; }\r\n.rechtstext h2:first-of-type{ margin-top:var(--r4); }\r\n.rechtstext h3{ margin-top:var(--r5); font-size:1.02rem; }\r\n.rechtstext p, .rechtstext li{ color:var(--text); font-size:.94rem; }\r\n.rechtstext ul{ padding-left:1.2rem; }\r\n.rechtstext li{ margin-bottom:var(--r1); }\r\n\r\n/* --- Anmeldung ----------------------------------------------------------- */\r\n.anmeldung-karte{ max-width:440px; margin:var(--r5) auto; border-top:4px solid var(--navy); }\r\n.anmeldung-karte img{ height:88px; width:auto; margin:0 auto var(--r4); display:block; --saum:1.5px; }\r\n.anmeldung-karte form{ text-align:left; }\r\n.anmeldung-fuss{\r\n  margin-top:var(--r5); padding-top:var(--r4); border-top:1px solid var(--linie);\r\n  display:flex; flex-direction:column; gap:var(--r2);\r\n  font-size:.85rem; text-align:center;\r\n}\r\n.code-feld{\r\n  font-family:var(--schrift-mono); font-size:1.5rem; letter-spacing:.5em;\r\n  text-align:center; padding-left:.5em;\r\n}\r\n\r\n/* --- Portfolio: was die AG schon gemacht hat ----------------------------- */\r\n/* Eine Karte zur Zeit: Die Erfolge bleiben vollst\u00e4ndig sichtbar, ohne dass\r\n   die Startseite durch zehn Eintr\u00e4ge unn\u00f6tig lang wird. */\r\n.portfolio-slideshow{ margin-top:var(--r6); }\r\n.portfolio{\r\n  margin:0; padding:0; position:relative;\r\n  min-height:12rem;\r\n}\r\n.portfolio-karte{\r\n  display:grid; grid-template-columns:7.5rem 1fr; gap:var(--r5);\r\n  align-items:start; padding:var(--r5);\r\n  position:relative; border:1px solid var(--linie);\r\n  border-left:4px solid var(--karte, var(--navy));\r\n  border-radius:var(--rund); background:var(--flaeche);\r\n  box-shadow:var(--schatten);\r\n}\r\n.portfolio-karte[hidden]{ display:none; }\r\n.portfolio-zeit{\r\n  font-family:var(--schrift-mono); font-size:.76rem; letter-spacing:.04em;\r\n  color:var(--gedaempft); text-align:right; padding-top:.35rem;\r\n  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\r\n}\r\n.portfolio-inhalt{\r\n  min-width:0; padding-left:var(--r2);\r\n}\r\n.portfolio-galerie{ position:relative; margin-bottom:var(--r3); }\r\n.portfolio-bild{\r\n  display:none; width:100%; padding:0; border:0; background:none;\r\n  cursor:zoom-in; text-align:left;\r\n}\r\n.portfolio-bild:first-child{ display:block; }\r\n.portfolio-bild img{\r\n  display:block; width:100%; max-height:20rem; object-fit:cover;\r\n  border-radius:var(--r2); margin:0;\r\n}\r\n.portfolio-bild-anzahl{\r\n  position:absolute; right:.65rem; bottom:.65rem; pointer-events:none;\r\n  padding:.2rem .55rem; border-radius:var(--rund-voll);\r\n  background:rgba(8,26,51,.82); color:#fff; font-size:.78rem;\r\n}\r\n.bild-dialog{\r\n  position:fixed; inset:0; z-index:100;\r\n  display:flex; align-items:center; justify-content:center;\r\n  padding:clamp(1rem, 4vw, 4rem);\r\n  background:rgba(8,15,26,.9);\r\n}\r\n.bild-dialog[hidden]{ display:none; }\r\n.bild-dialog-bild{\r\n  max-width:min(92vw, 1100px); max-height:88vh; object-fit:contain;\r\n  border-radius:var(--rund-klein); box-shadow:0 16px 50px rgba(0,0,0,.45);\r\n}\r\n.bild-dialog-schliessen,.bild-dialog-pfeil{\r\n  position:absolute; display:flex; align-items:center; justify-content:center;\r\n  width:2.8rem; height:2.8rem; padding:0; border:1px solid rgba(255,255,255,.3);\r\n  border-radius:50%; background:rgba(8,26,51,.8); color:#fff; cursor:pointer;\r\n}\r\n.bild-dialog-schliessen{ top:1.2rem; right:1.2rem; font-size:1.8rem; }\r\n.bild-dialog-pfeil{ top:50%; transform:translateY(-50%); font-size:2rem; }\r\n.bild-dialog-zurueck{ left:1.2rem; }\r\n.bild-dialog-weiter{ right:1.2rem; }\r\n.bild-dialog-pfeil[hidden]{ display:none; }\r\n.portfolio-inhalt h3{ margin:0 0 var(--r2); font-size:1.08rem; }\r\n.portfolio-inhalt p{ margin:0 0 var(--r2); color:var(--gedaempft); font-size:.94rem; }\r\n.portfolio-inhalt p:last-child{ margin-bottom:0; }\r\n.portfolio-ergebnis{\r\n  display:inline-block; margin-top:var(--r1) !important;\r\n  padding:.25rem .7rem; border-radius:var(--rund-voll);\r\n  background:color-mix(in srgb, var(--karte, var(--navy)) 12%, transparent);\r\n  border:1px solid color-mix(in srgb, var(--karte, var(--navy)) 30%, transparent);\r\n  color:var(--text) !important; font-size:.86rem !important; font-weight:600;\r\n}\r\nhtml[data-theme=\"dark\"] .portfolio-ergebnis{\r\n  background:color-mix(in srgb, var(--karte, var(--navy)) 20%, var(--flaeche));\r\n}\r\n.portfolio-steuerung{\r\n  display:flex; align-items:center; justify-content:center;\r\n  gap:var(--r4); margin-top:var(--r4);\r\n}\r\n.portfolio-pfeil{\r\n  display:flex; align-items:center; justify-content:center;\r\n  width:2.5rem; height:2.5rem; padding:0; border:1px solid var(--linie);\r\n  border-radius:50%; background:var(--flaeche); color:var(--navy);\r\n  font-size:1.8rem; line-height:1; cursor:pointer;\r\n}\r\n.portfolio-pfeil:hover{ background:var(--navy-hauch); border-color:var(--navy); }\r\n.portfolio-punkte{ display:flex; align-items:center; gap:.45rem; }\r\n.portfolio-punkt{\r\n  width:.55rem; min-width:.55rem; height:.55rem; min-height:.55rem;\r\n  padding:0; border:0; border-radius:50%;\r\n  background:var(--gedaempft-2); cursor:pointer; opacity:.55;\r\n  transition:width var(--tempo) ease, border-radius var(--tempo) ease,\r\n             opacity var(--tempo) ease, background var(--tempo) ease;\r\n}\r\n.portfolio-punkt[aria-selected=\"true\"]{\r\n  width:1.8rem; background:var(--amber); border-radius:var(--rund-voll);\r\n  opacity:1;\r\n}\r\n@media (max-width:720px){\r\n  .portfolio-karte{ grid-template-columns:1fr; gap:var(--r1); padding:var(--r4); }\r\n  .portfolio-zeit{ text-align:left; padding-top:0; }\r\n  .bild-dialog-pfeil{ width:2.4rem; height:2.4rem; }\r\n  .bild-dialog-zurueck{ left:.5rem; }\r\n  .bild-dialog-weiter{ right:.5rem; }\r\n}\r\n\r\n/* Die Notluke am zweiten Faktor - unauffaellig, aber auffindbar. */\r\n.anmeldung-hilfe{ margin:var(--r3) 0 0; text-align:left; }\r\n.anmeldung-hilfe summary{\r\n  cursor:pointer; font-size:.86rem; color:var(--gedaempft);\r\n  padding:.35rem 0; min-height:2rem; display:flex; align-items:center;\r\n}\r\n.anmeldung-hilfe summary:hover{ color:var(--text); }\r\n.anmeldung-hilfe .meta{ margin:.2rem 0 0; }\r\n\r\n/* Der Haken \"Angemeldet bleiben\" - links am Rand, wie die Beschriftungen\r\n   darueber, und mit genug Flaeche zum Treffen. */\r\n.angemeldet-bleiben{\r\n  display:flex; align-items:flex-start; gap:var(--r2);\r\n  margin:var(--r3) 0 var(--r4); text-align:left; cursor:pointer;\r\n  font-size:.92rem;\r\n}\r\n.angemeldet-bleiben input{ margin-top:.15rem; flex-shrink:0; }\r\n.angemeldet-bleiben .meta{ display:block; margin:.1rem 0 0; }\r\n";

